add_filter( 'woocommerce_get_order_item_totals', 'perfectpixel_extra_order_totals_row', 20, 2 );

function perfectpixel_extra_order_totals_row( $rows, $order ) {
	$value = '{{totals_row_value}}';
	if ( false !== strpos( $value, '{savings}' ) ) {
		$discount = (float) $order->get_discount_total() + (float) $order->get_discount_tax();
		if ( $discount <= 0 ) {
			return $rows;
		}
		$value = str_replace( '{savings}', wp_strip_all_tags( wc_price( $discount, array( 'currency' => $order->get_currency() ) ) ), $value );
	}
	$row = array(
		'perfectpixel_extra' => array(
			'label' => '{{totals_row_label}}',
			'value' => esc_html( $value ),
		),
	);
	// Insert before the grand total when present.
	$pos = array_search( 'order_total', array_keys( $rows ), true );
	return false === $pos ? $rows + $row : array_slice( $rows, 0, $pos, true ) + $row + array_slice( $rows, $pos, null, true );
}
